function runSelfTests(){var failures=[];function assert(condition,message){if(!condition)failures.push(message);}assert(new Set(CATEGORIES.map(function(c){return c.id;})).size===CATEGORIES.length,"duplicate category id");assert(new Set(FAMILIES.map(function(f){return f.id;})).size===FAMILIES.length,"duplicate family id");assert(FAMILIES.length===75,"all 75 specified families registered");FAMILIES.forEach(function(f,familyIndex){assert(CATEGORIES.some(function(c){return c.id===f.categoryId;}),f.id+": category exists");LEVELS.forEach(function(level){var signatures=new Set();for(var sample=0;sample<24;sample+=1){var seed=((familyIndex+1)*100000+level*1000+sample+1)>>>0;try{var q=generateQuestion(f.id,level,seed);assert(q.familyId===f.id,f.id+": stable family id");assert(q.prompt.title&&q.prompt.blocks.length&&q.explanation,f.id+": rendering metadata");assert(checkQuestion(q.canonicalAnswer,q).correct,f.id+": canonical answer rejected L"+level+" seed "+seed);assert(!checkQuestion({},q).correct||q.fields.every(function(field){return String(field.answer)==="";}),f.id+": empty malformed answer accepted");assert(q.metadata.dialectVersion===MODEL_ID&&q.metadata.oracleVersion===ORACLE_VERSION,f.id+": pinned model metadata");signatures.add(q.structuralSignature);}catch(error){failures.push(f.id+" L"+level+" seed "+seed+": "+error.message);}}assert(signatures.size>=2,f.id+": insufficient structural variation L"+level);});});
assert(eq3(null,null)==="U"&&eq3(2,2)==="T","ordinary NULL comparison");assert(and3("F","U")==="F"&&or3("T","U")==="T"&&not3("U")==="U","three-valued truth tables");assert(in3(3,[1,2,null])==="U"&&in3(2,[1,2,null])==="T","nullable IN");assert(bagEqual([[1],[1],[2]],[[2],[1],[1]])&&!bagEqual([[1],[2]],[[1],[1],[2]]),"bag multiplicity oracle");assert(likeMatch("10%%","10!%%","!")&&!likeMatch("100%","10!%%","!"),"LIKE escape oracle");assert(closure(["A"],[[["A"],["B"]],[["B"],["C"]]]).join("")==="ABC","attribute closure oracle");assert(joinRows([{k:null}],[{r:null}],"k","r",false,false).length===0,"NULL join equality");assert(aggregates([1,null,1]).countStar===3&&aggregates([1,null,1]).count===2&&aggregates([1,null,1]).countDistinct===1,"aggregate NULL oracle");assert(indexPrefix(["a","b"],{a:"eq",b:"range"})===2&&indexPrefix(["a","b"],{b:"eq"})===0,"B-tree prefix oracle");if(TEXT.localeCode!=="en"){assert(CATEGORIES.every(function(c){return Boolean(t("categories."+c.id,null));}),"localized categories complete");assert(FAMILIES.every(function(f){return Boolean(t("families."+f.id,null)&&t("familyRules."+f.id,null)&&t("familyExamples."+f.id,null));}),"localized family learn content complete");}return{ok:failures.length===0,failures:failures};}
window.SqlRelationalDatabasesApp={modelId:MODEL_ID,oracleVersion:ORACLE_VERSION,categories:CATEGORIES,families:FAMILIES,generateQuestion:generateQuestion,checkQuestion:checkQuestion,oracles:{not3:not3,and3:and3,or3:or3,eq3:eq3,cmp3:cmp3,in3:in3,bagEqual:bagEqual,distinctRows:distinctRows,likeMatch:likeMatch,closure:closure,joinRows:joinRows,aggregates:aggregates,indexPrefix:indexPrefix}};window.runSelfTests=runSelfTests;document.addEventListener("DOMContentLoaded",init);
